    /// <summary>Points the data folder to a fresh temporary demo folder. Must run before anything reads AppPaths.</summary>
    public static void UseDemoFolder()
    {
        if (Environment.GetEnvironmentVariable("MAILSTUDIO_DATA_DIR") is { Length: > 0 }) return;
        var dir = Path.Combine(Path.GetTempPath(), "MailStudio-Demo");
        try { if (Directory.Exists(dir)) Directory.Delete(dir, true); } catch { }
        Environment.SetEnvironmentVariable("MAILSTUDIO_DATA_DIR", dir);
    }

