    /// <summary>Creates the demo account, mails and attachment files (idempotent).</summary>
    public static AccountConfig Seed(AccountStore store, MailCache cache)
    {
        var en = L.IsEnglish;
        var acc = store.Accounts.FirstOrDefault(a => a.Id == AccountId);
        if (acc == null)
        {
            acc = new AccountConfig
            {
                Id = AccountId, DisplayName = en ? "Demo User" : "Demo Kullanıcı", Email = "demo@mailstudio.example",
                ImapHost = Host, SmtpHost = Host, OfflineAttachments = true,
                Signatures = { new MailSignature { Id = "demo-sig", Name = en ? "Default" : "Varsayılan", Html = "<p>Best regards,<br><b>Demo User</b><br>MailStudio for TRMachinist</p>" } },
                DefaultSignatureId = "demo-sig",
            };
            store.Accounts.Add(acc);
            store.Save();
        }
        if (AppSettings.Shared.AiProvider != "Demo AI") { AppSettings.Shared.AiProvider = "Demo AI"; AppSettings.Shared.Save(); }
        if (AppSettings.Shared.FormatRules.Count == 0)
        {
            AppSettings.Shared.FormatRules.Add(new FormatRule { Name = en ? "Customer quotations" : "Müşteri teklifleri", TextColor = "#0F6CBD", Bold = true,
                Conditions = { new FormatCondition { Field = "subject", Value = en ? "Quotation" : "Teklif" } } });
            AppSettings.Shared.FormatRules.Add(new FormatRule { Name = en ? "CAD and CNC attachments" : "CAD ve CNC ekleri", TextColor = "#B4009E",
                Conditions = { new FormatCondition { Field = "text", Value = "STEP;OP20;DXF" } } });
            AppSettings.Shared.FormatRules.Add(new FormatRule { Name = en ? "Newsletters" : "Bültenler", TextColor = "#8A8886", Italic = true,
                Conditions = { new FormatCondition { Field = "from", Value = "news@" } } });
            AppSettings.Shared.Save();
        }
        var files = Path.Combine(AppPaths.Root, "demo-files");
        Directory.CreateDirectory(files);
        var source = Path.Combine(AppContext.BaseDirectory, "Demo");
        if (Directory.Exists(source))
            foreach (var f in Directory.GetFiles(source)) File.Copy(f, Path.Combine(files, Path.GetFileName(f)), true);

        var now = DateTimeOffset.Now;
        var headers = new List<MailHeader>();
        foreach (var m in Mails)
        {
            var subject = en ? m.SubjectEn : m.SubjectTr;
            var html = en ? m.BodyEn : m.BodyTr;
            var text = System.Text.RegularExpressions.Regex.Replace(WebUtility.HtmlDecode(System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ")), "\\s+", " ").Trim();
            var h = new MailHeader
            {
                AccountId = AccountId, Folder = m.Folder, Uid = m.Uid, UidValidity = 1, MessageId = $"demo-{m.Uid}@mailstudio.example",
                FromName = m.FromName, FromAddress = m.FromAddress, To = "demo@mailstudio.example", Subject = subject,
                Preview = text.Length > 160 ? text[..160] : text, Date = now.AddHours(-m.HoursAgo), HasAttachments = m.Files?.Length > 0,
            };
            h.IsRead = m.Read; h.IsFlagged = m.Flagged;
            headers.Add(h);
        }
        cache.UpsertHeaders(headers);
        foreach (var m in Mails)
        {
            var atts = (m.Files ?? Array.Empty<string>()).Select(f => new AttachmentInfo
            {
                FileName = f, Part = f, Size = File.Exists(Path.Combine(files, f)) ? new FileInfo(Path.Combine(files, f)).Length : 1024,
            }).ToList();
            cache.SaveBody(AccountId, m.Folder, m.Uid, new MailContent { Html = WrapHtml(L.IsEnglish ? m.BodyEn : m.BodyTr), Text = MailService.HtmlToText(L.IsEnglish ? m.BodyEn : m.BodyTr), Attachments = atts });
            cache.SaveAttachments(AccountId, m.Folder, m.Uid, atts);
        }
        return acc;
    }

    static string WrapHtml(string body) => "<div style=\"font-family:Segoe UI,Calibri,sans-serif;font-size:14px\">" + body + "</div>";

    public static bool IsDemo(AccountConfig a) => a.ImapHost == Host;

